const durationInMilliseconds = 45 * 60 * 1000;
const newTimeValue = dateObj.getTime() + durationInMilliseconds;

// 4. Create a NEW Date object for the end time to avoid reference issues
const endDateObj = new Date(newTimeValue);

return {
    start_time: startTimeString, // The original string
    end_time: endDateObj.toISOString() // The calculated ISO string
};

