return $input.all().map(item => {

  // --- A. INCOME ---
  const incomeVal = $('Webhook').first().json.body.meetData.attendees[0].answers[4].answer; 
  item.json['income_id'] = incomeMap[incomeVal] || null;

  // --- B. ZOOM CONFIRMATION ---
  const zoomVal = $('Webhook').first().json.body.meetData.attendees[0].answers[6].answer; 
  item.json['zoom_confirmation_id'] = zoomMap[zoomVal] || null;

  // --- C. ATTENDANCE (Fixed Reference) ---
  // Using the Webhook reference directly as you requested
  // Note: Ensure index [5] is exactly where the answer lives
  const attendanceVal = $('Webhook').first().json.body.meetData.attendees[0].answers[5].answer;
  item.json['attendance_id'] = attendanceMap[attendanceVal] || null;

  // --- D. GROWTH COMMITMENT ---
  const growthVal = $('Webhook').first().json.body.meetData.attendees[0].answers[8].answer;
  item.json['growth_commitment_id'] = growthMap[growthVal] || null;

  // --- E. VIDEO WATCHED ---
  const videoVal = $('Webhook').first().json.body.meetData.attendees[0].answers[9].answer;
  item.json['video_watched_id'] = videoMap[videoVal] || null;

  return item;
});

