const item = $input.item.json;

// Get the text content from the nested output
const text = item.output?.[0]?.content?.[0]?.text || '';

// Parse the JSON string inside the text
let parsed = { marketing_score: null, key_points: '' };
try {
  const clean = text.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch(e) {
  // keep defaults
}

return [{
  json: {
    ...item,
    marketing_score: parsed.marketing_score,
    key_points_before_call: parsed.key_points
  }
}];

const lead = $input.item.json;
const cf = lead.customFieldValues || {};
const meta = lead.metaData?.idNameStore || {};

// System fields to skip (not Q&A)
const skipFields = new Set([
  'updatedBy', 'createdBy', 'ownerId', 'source',
  'cfLeadType', 'cfSubSourceMultiPicklist', 'cfZoomMeetingLink', 'cfZoomMeetingId'
]);

// Build Q&A pairs from customFieldValues
const qa = {};
for (const key of Object.keys(cf)) {
  if (skipFields.has(key)) continue;

  const label = key
    .replace(/^cf/, '')
    .replace(/([A-Z])/g, ' $1')
    .trim();

  const metaVal = meta[key] ? Object.values(meta[key])[0] : null;
  const rawVal = cf[key];
  qa[label] = metaVal || rawVal;
}

return [{
  json: {
    ...lead,
    lead_qa: qa,
    lead_qa_for_gpt: JSON.stringify(qa, null, 2)
  }
}];

